def is_plain_name(name: str) -> bool:
    """True when name is one ordinary path component: non-empty, not '.' or '..', with no '/' or '\\' and no NUL."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../x") == False
    ex is_plain_name("sub/a") == False
    if name == "" or name == "." or name == "..":
        return False
    if "/" in name or "\\" in name or "\0" in name:
        return False
    return True

def read_note(name: str) -> str uses fs:
    """Contents of file name inside the notes directory; empty string when it is missing or unreadable. Confines fs to notes with fs.sub before reading."""
    pre is_plain_name(name)
    with fs = fs.sub("notes"):
        return fs.read_text(name) else ""

def count_readable(names: list[str]) -> int uses fs:
    """Number of names that are readable files inside the notes directory. Unsafe names are never read and count as unreadable."""
    post out >= 0 and out <= names.len()
    count = 0
    for name in names:
        if not is_plain_name(name):
            continue
        text = read_note(name)
        if text != "":
            count += 1
    return count
